const normalizuj = (tekst) => tekst.toLowerCase().replace(/\s+/g, ' ');

const wynik = []
for (const item of $input.all()) {
  if (!item.json.quote) {
    wynik.push({ json: { ...item.json,
                       quote_found: false} });
    continue;
  }
  const q = normalizuj(item.json.quote);
  const s = normalizuj(item.json.contentSnippet);
  wynik.push({ json: {
    ...item.json,
    no_claims: false,
    quote_found: s.includes(q)
  }});
}
return wynik;

const artykuly = $('Limit').all();   
const wynik = [];

for (let i = 0; i < $input.all().length; i++) {
  const claims = $input.all()[i].json.output.claims;   
  const zrodlo = artykuly[i].json; 

  if (claims.length === 0) {
      wynik.push({
        json: {
          contentSnippet: zrodlo.contentSnippet,
          title: zrodlo.title,
          link: zrodlo.link,
          no_claims: true
        }
      });
      continue;
    }

  for (const c of claims) {
    wynik.push({
      json: {
        claim: c.claim,
        quote: c.quote,
        contentSnippet: zrodlo.contentSnippet,
        title: zrodlo.title,
        link: zrodlo.link
      }
    });
  }
}

return wynik;

const full_list = $('Code2').all()
const indexes = [];

for (let i = 0; i < full_list.length; i++) { 
  const source = full_list[i].json; 

  if (source.no_claims === false && source.quote_found === true) {
      indexes.push(i);
    }
}
if (indexes.length !== $input.all().length) {
  throw new Error(`Mapowanie sędziego niepoprawne. Indeksy: ${indexes.length}. Itemy: ${$input.all().length}. full_list: ${full_list.length}`)
}

const judged_items = $input.all();
let judged = 0;
const output = [];

for (let i = 0; i < full_list.length; i++) {
  const source = full_list[i].json;

  if (source.no_claims === true){
    output.push({ json: {
      status: "no_claims_stated",
      title: source.title,
      link: source.link,
      pubDate: source.pubDate
    }});
    continue;
  }

  if (source.quote_found === false) {
    output.push({ json: {
      status: "quote_not_found",
      title: source.title,
      link: source.link,
      pubDate: source.pubDate,
      claim: source.claim,
      quote: source.quote
    }});
    continue;
  } 

  const verdict = judged_items[judged].json.output; judged++;
  if (verdict.within_scope === false) {
    output.push({ json: {
      status: "claim_out_of_scope",
      title: source.title,
      link: source.link,
      pubDate: source.pubDate,
      claim: source.claim,
      quote: source.quote,
      reason: verdict.reason
    }});
    continue;
  } 
  output.push({ json: {
    status: "verified",
    title: source.title,
    link: source.link,
    pubDate: source.pubDate,
    claim: source.claim,
    quote: source.quote,
    reason: verdict.reason
  }});
}

return output
